WITH overlapping AS ( SELECT cc.cc_call_center_sk, cc.cc_country AS country, cc.cc_state AS state, cc.cc_city AS city, cc.cc_employees AS employees, ws.web_site_sk, ws.web_name, w.w_warehouse_sk, w.w_warehouse_name, DATE_DIFF('day', GREATEST(cc.cc_rec_start_date, ws.web_rec_start_date), LEAST(cc.cc_rec_end_date, ws.web_rec_end_date)) + 1 AS overlap_days FROM call_center cc JOIN web_site ws ON cc.cc_country = ws.web_country AND cc.cc_state = ws.web_state AND cc.cc_city = ws.web_city JOIN warehouse w ON cc.cc_country = w.w_country AND cc.cc_state = w.w_state AND cc.cc_city = w.w_city WHERE cc.cc_rec_end_date >= cc.cc_rec_start_date AND ws.web_rec_end_date >= ws.web_rec_start_date ) SELECT country, state, city, SUM(employees) AS total_employees, SUM(overlap_days) AS total_overlap_days, COUNT(DISTINCT cc_call_center_sk) AS num_call_centers, COUNT(DISTINCT web_site_sk) AS num_web_sites, COUNT(DISTINCT w_warehouse_sk) AS num_warehouses, AVG(overlap_days) AS avg_overlap_days, RANK() OVER (ORDER BY SUM(employees) DESC) AS employee_rank FROM overlapping WHERE overlap_days > 0 GROUP BY country, state, city HAVING SUM(employees) > 1000000 ORDER BY total_employees DESC LIMIT 50
